const box=document.getElementById('storyboard');let generation=0;const cache=new Map();
function initial(){box.replaceChildren();for(let i=1;i<=6;i++){const tile=document.createElement('button');tile.className='story-shot';tile.setAttribute('aria-label','加载示例视频');const img=document.createElement('img');img.src=`assets/still-${i}.jpg`;img.alt='创作示例画面';const label=document.createElement('small');label.textContent=`示例画面 ${String(i).padStart(2,'0')}`;tile.append(img,label);tile.onclick=()=>document.getElementById('demo').click();box.append(tile)}}initial();
async function thumbnail(asset,time){const key=asset.url+':'+time.toFixed(2);if(cache.has(key))return cache.get(key);const v=document.createElement('video');v.muted=true;v.preload='auto';await new Promise((resolve,reject)=>{const t=setTimeout(()=>reject(Error('超时')),12000);v.onloadeddata=()=>{clearTimeout(t);resolve()};v.onerror=()=>{clearTimeout(t);reject(Error('读取失败'))};v.src=asset.url});if(time>.02)await new Promise((resolve,reject)=>{const t=setTimeout(()=>reject(Error('超时')),12000);v.onseeked=()=>{clearTimeout(t);resolve()};v.currentTime=time});const c=document.createElement('canvas');c.width=320;c.height=190;const ctx=c.getContext('2d');ctx.fillStyle='#e7e0d3';ctx.fillRect(0,0,320,190);const scale=Math.min(320/v.videoWidth,190/v.videoHeight);ctx.drawImage(v,(320-v.videoWidth*scale)/2,(190-v.videoHeight*scale)/2,v.videoWidth*scale,v.videoHeight*scale);const url=c.toDataURL('image/jpeg',.75);v.removeAttribute('src');v.load();cache.set(key,url);return url}
document.addEventListener('plan-update',async e=>{const id=++generation;const {clips,assets}=e.detail;box.replaceChildren();if(!clips.length){const empty=document.createElement('span');empty.className='storyboard-empty';empty.textContent='添加片段，开始安排你的故事。';box.append(empty);return}let offset=0;for(let i=0;i<clips.length;i++){const clip=clips[i];const tile=document.createElement('button');tile.className='story-shot'+(i===0?' selected':'');const img=document.createElement('img');img.alt=`镜头 ${i+1}：${assets[clip.asset]?.name||'待检查素材'}`;const label=document.createElement('small');const start=offset;offset+=Math.max(0,clip.end-clip.start);label.textContent=`${start.toFixed(1)} — ${offset.toFixed(1)} 秒`;tile.append(img,label);tile.onclick=()=>{box.querySelectorAll('.selected').forEach(el=>el.classList.remove('selected'));tile.classList.add('selected');document.querySelectorAll('#timeline>.clip')[i]?.querySelector('button:last-child')?.click()};box.append(tile);if(assets[clip.asset])thumbnail(assets[clip.asset],Math.max(0,Math.min(clip.start,assets[clip.asset].duration-.05))).then(url=>{if(generation===id)img.src=url}).catch(()=>{img.alt='暂无法提取预览帧，请检查时间区间'})}});
